# Glossary of named things across the CIDM 6333 decks.
# Fields: term, cat, aliases (also matched when auto-linking), what, when (who/when), why (why it is in the course),
# src (where to read more), ch (textbook chapters). Course vocabulary follows Appendix D of the Course Topic Guide and the decks.
# Categories: course · harness · protocol · system · paper · bench · method · org

E = []
def g(term, cat, what, when="", why="", src="", aliases=(), ch=()):
    E.append(dict(term=term, cat=cat, what=what, when=when, why=why, src=src, aliases=list(aliases), ch=list(ch)))

# ---------------- course vocabulary ----------------
g("Evolution", "course", "An Evolution is the course's unit of progression. Each one pairs one lecture with one build and one sortie, and each adds one layer to the system. E0 is orientation. E1 through E12 add the loop, patterns, tools, MCP, the harness, context, memory, coordination, failure, evaluation, observability, and deployment, in that order. An Evolution compresses or expands to fit the time available, and the order of the layers does not change.", "", "Every deck, exercise, and flight card in the course is filed by its Evolution number.", "Course Topic Guide, Using this book", aliases=("Evolutions", "E0", "E1", "E2", "E3", "E4", "E5", "E6", "E7", "E8", "E9", "E10", "E11", "E12"), ch=(22,))
g("Sprint and Drift", "course", "Sprint and Drift is the method by which the student does the work and the instructor examines it. In the Sprint, the student produces the work with AI and logs what the AI did. In the Drift, the student defends the work without AI, to a reader who can ask why. The two terms come from naval practice, where a ship cannot move and listen at once.", "The instructor developed the method for CIDM 6330 (Software Architecture) and carried it into CIDM 6333.", "The AI log and the Drift, not the artifact alone, are where the course checks understanding.", "Course Topic Guide, Chapter 22; sprintanddrift.substack.com", aliases=("Sprint", "Drift", "The Sprint", "Drifts"), ch=(22,))
g("Sortie", "course", "A sortie is one flight of one flight card in one sitting. The student runs the build against the design claim pre-registered on the card and records what came back. Sortie 7 flies Flight Card 7, and the numbering continues in the same way.", "The term is borrowed from aircraft flight test.", "The sortie is the course's unit of evidence.", "Course Topic Guide, Chapter 23", aliases=("Sorties", "Sortie 1", "Sortie 7", "Sortie 8", "Sortie 9", "Sortie 10", "Sortie 11"), ch=(23,))
g("Flight card", "course", "A flight card is the plan for a sortie, written and committed before the run. It states the design claim, the envelope (center, corner, or expansion), the systems under test, the substrate, the test points, the instrumentation, the entry conditions, and the falsifiers. The flight log is the companion record of what happened when the card flew.", "Appendix A of the Course Topic Guide gives the template.", "A run counts as evidence only if the card was written before it. A card written afterward can be fitted to whatever happened.", "Course Topic Guide, Chapter 23 and Appendix A", aliases=("Flight Card", "flight cards", "Flight Card 1", "Flight Card 7", "Flight Card 8", "Flight Card 10", "FC2", "FC3", "flight log", "Flight log", "ENVELOPE", "TEST POINTS", "INSTRUMENTATION", "ENTRY CONDITIONS", "SYSTEMS UNDER TEST", "SUBSTRATE", "PRE-REGISTERED FALSIFIERS", "DESIGN CLAIM"), ch=(23,))
g("Falsifier", "course", "A falsifier is an observation, written on the flight card before the sortie, that would show the design claim to be false. The verdict after the sortie is REFUTED or NOT-REFUTED, and 'it worked' is not a verdict.", "The term comes from Karl Popper's falsificationism, applied here to engineering design claims.", "The course scores a design claim by what would have refuted it, not by whether the demo ran.", "Course Topic Guide, Chapter 23", aliases=("Falsifiers", "falsifiers", "REFUTED", "NOT-REFUTED"), ch=(23,))
g("Chase", "course", "The Chase is the independent observer of a sortie. A classmate takes the role and writes the verdict from the evidence alone (the ledger, the receipts, the test output), without relying on the pilot's account.", "The term comes from flight test, where a chase plane watches the test aircraft from outside.", "Every sortie has a Chase. The Chase writes the Go/No-Go before the sortie and the review after it, and both are committed to the repository.", "Course Topic Guide, Chapter 23", aliases=("The Chase", "Your Chase", "CHASE", "Chase review"), ch=(23,))
g("Go / No-Go", "course", "Go / No-Go is the Chase's written decision that a sortie may fly, because the entry conditions on the flight card are met, or may not. The Chase records it in the repository before the sortie.", "", "A sortie flown without a Go is unplanned, and the course does not count its result as evidence.", "Course Topic Guide, Chapter 23", aliases=("No-Go", "NO-GO", "Go/No-Go"), ch=(23,))
g("Squawk", "course", "A squawk is an anomaly recorded at the debrief after a sortie and routed to a destination: an issue, a feedback entry, an amendment to the flight card, or a re-fly.", "In aviation a squawk is a maintenance write-up.", "The debrief is where a finding becomes a work item rather than a memory.", "Course Topic Guide, Appendix D", aliases=("squawks",), ch=(23,))
g("Design Analysis", "course", "A Design Analysis is the course's procedure for taking a system apart. It lists the nine components (perception, reasoning, planning, action, memory, tools, coordination, evaluation, governance), states the mechanism behind each, and ends with one 'why' paragraph that states the problem the design answered and what the design cost.", "Appendix B of the Course Topic Guide gives the template, and the Teardown segment of a lecture, when it has one, performs one live.", "The survey half of the course asks the same question of every system: why was it designed this way?", "Course Topic Guide, Chapter 24 and Appendix B", aliases=("Design Analyses", "Live Design Analysis", "Design Analysis Ledger", "nine components"), ch=(24, 2))
g("Teardown", "course", "A Teardown is the lecture segment that takes one real system apart with the Design Analysis. The subjects include FIPA and BDI, CAMEL and MetaGPT, the LangGraph supervisor, and Claude Code subagents. Each Teardown ends with the mechanism, the design choice, the cost, and the failure mode.", "", "The Teardown is the survey thread of each Evolution, the part of the lecture that examines systems other people built.", "Course Topic Guide, Chapter 24", aliases=("Teardowns",), ch=(24,))
g("Final System", "course", "The Final System is the end-of-course build. The student uses the harness assembled across the Evolutions to build an MVP tied to the E0 pitch, with verification and validation that assures the harness's actions, and a real user validates the result at the closeout.", "", "", "Course Topic Guide, Chapter 26; the Final System handout", aliases=("The Final System", "closeout", "closeout ceremony", "Closeout"), ch=(26,))
g("Index zero", "course", "Index zero is the human's position in the system. The human is first in priority, because the human's intent drives every decision, and final in authority, because the human signs off and the model does not. The Zero Doctrine is gzkit's statement of this position, and it is the answer to the Degradation Pattern.", "The term is gzkit's, and the E0 lecture takes it as its title.", "Everything in the course's governance follows from it: the gates, attestation, and the Chase.", "Course Topic Guide, Chapter 3", aliases=("index zero", "Index Zero", "Zero Doctrine"), ch=(3,))
g("Degradation Pattern", "course", "The Degradation Pattern is the slide in human review that occurs as a model keeps producing acceptable output. Careful reading becomes skimming, skimming becomes approving, and approving becomes absence. The system still runs, and nobody is answering for it. The course describes the slide under three names: cognitive surrender (the human stops judging), mediated observation (the human sees only what the model reports), and governance theater (the gates exist on paper and nothing enforces them).", "Chapter 3 of the Course Topic Guide and the E0 lecture introduce it.", "The course's governance apparatus exists to interrupt this slide.", "Course Topic Guide, Chapter 3", aliases=("Degradation", "cognitive surrender", "mediated observation", "governance theater"), ch=(3,))
g("Covenant", "course", "The covenant is gzkit's five-clause agreement between the human and the agent. It states what each may do and what each must record. Governance, in the course's sense, is this agreement plus the mechanisms that enforce it.", "", "", "Course Topic Guide, Chapter 3", aliases=("covenant", "the covenant"), ch=(3,))
g("Five gates", "course", "The five gates are gzkit's checkpoints on a piece of work. Gate 1 is the ADR (the decision is written). Gate 2 is TDD (a test exists and was red first). Gate 3 is Docs. Gate 4 is BDD (behavioral acceptance). Gate 5 is human attestation. The Lite lane runs gates 1 and 2, and the Heavy lane runs all five.", "", "The course uses the gates to place a model's self-review: it counts at most as Gate-4 evidence and never as Gate 5 (rule GZK-GOV-007).", "Course Topic Guide, Chapter 3", aliases=("Gate", "Gates", "Gate 4", "Gate 5", "Gate-4", "Gate-5", "Lite", "Heavy", "lane", "Lane", "GZK-GOV-007"), ch=(3,))
g("Attestation", "course", "An attestation is a human's recorded judgment that a piece of work is Completed, Completed — Partial, or Dropped. It is Gate 5. A later reader can repudiate it if the record shows the work did not exist as attested.", "The term is gzkit's, and the June 2026 repudiations in the incident casebook are the worked example.", "", "Course Topic Guide, Appendix D and Appendix G", aliases=("attestation", "attestations", "Attestations", "repudiation"), ch=(3, 9))
g("Ledger", "course", "The ledger is the append-only event log that records every command, verdict, gate, and attestation with its date. It is the system's runtime truth, the L2 layer. gzkit writes it as JSONL, and the course asks the student's harness to keep one too.", "The term is gzkit's.", "'The ledger is the black box.' Anything a person or a model says about a run is a claim, and the ledger is the evidence the claim is checked against.", "Course Topic Guide, Appendix D", aliases=("ledger", "ledger.jsonl", "the ledger"), ch=(3, 12))
g("Receipt", "course", "A receipt is a schema-validated record of a command's observed result. It holds the command, its exit code, the hash of its output, and the time it ran. A claim without a receipt is not evidence.", "The term is gzkit's.", "Sortie 9's falsifier is 'a claim in the flight log with no receipt'.", "Course Topic Guide, Appendix D", aliases=("receipts", "Receipts"), ch=(18, 20))
g("Layers of truth", "course", "The layers of truth are gzkit's three classes of record. L1 is canon, the files in the repository (intent, ADRs, AGENTS.md). L2 is the ledger, the record of what happened. L3 is derived, anything a model wrote about L1 or L2 (summaries, memory). In precedence, L2 beats L1 and L1 beats L3. The file beats the memory of the file.", "gzkit ADR-0.0.9 states the doctrine.", "Figure 14 and the memory Evolution apply the precedence rule: a retrieved record is L3, so it loses to the file it describes.", "Course Topic Guide, Appendix D", aliases=("layers of truth", "L1", "L2", "L3", "canon", "CANON", "DERIVED"), ch=(15,))
g("Brief (OBPI)", "course", "A brief is gzkit's unit of human review, and OBPI stands for One Brief Per Item. A brief states the requirements, acceptance criteria, and verification for one piece of work. The requirements are numbered (REQ-1, REQ-2) so that a reviewer can cite the one a change fails.", "", "", "Course Topic Guide, Appendix D", aliases=("OBPI", "brief", "briefs", "B-07"), ch=(25,))
g("ADR", "course", "An ADR is an Architecture Decision Record. It states the intent, the decision, the consequences, and the alternatives, and it is written before the code. The course's ADR-1 (E2) and ADR-2 (E7) are the student's own. gzkit's ADRs are numbered by release (ADR-0.18.0).", "Michael Nygard published the template in 2011 (title, context, decision, status, consequences). The course adds intent and alternatives, as CIDM 6330 does. The decks cite these gzkit ADRs: 0.0.2 (a standard-library CLI, argparse over click: popularity is not rationale), 0.0.9 (the state doctrine, layers of truth), 0.0.31 (the distribution invariant), 0.0.37 (AGENTS.md is rendered, not hand-edited), 0.0.54 (AGENTS.md is a map, not an encyclopedia), 0.0.71 (the first repudiated attestation), 0.0.73 (the hollow antibody), 0.0.74 (MX mode), 0.18.0 (the subagent pipeline).", "Gate 1 asks whether the ADR exists. A decision with no record cannot be defended in the Drift.", "https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions", aliases=("ADRs", "ADR-1", "ADR-2", "ADR-0.18.0", "ADR-0.0.71", "ADR-0.0.74", "ADR-0.0.2", "ADR-0.0.9", "ADR-0.0.31", "ADR-0.0.37", "ADR-0.0.54", "ADR-0.0.73"), ch=(25,))
g("PRD", "course", "A PRD is a Product Requirements Document. It states what the system is for and what it must do, and the student writes it in E1 before the loop exists. Flight cards take their DESIGN CLAIM and falsifiers from it.", "", "", "Course Topic Guide, Chapter 25", aliases=("docs/prd.md",), ch=(25,))
g("RED witness", "course", "A RED witness is proof that a test fails without the change it covers. The test is recorded red before the code makes it green. Mutation testing is the general form of the idea, and gzkit records the witness with gz arb red.", "The idea is TDD's red-green discipline. DeMillo, Lipton & Sayward (1978) is the source for mutation testing.", "Sortie 10's design claim in E10 is that the gate fails when it should, and the RED witness is the evidence that shows it.", "Course Topic Guide, Appendix D", aliases=("RED", "red witness", "Red Witness"), ch=(19,))
g("Expansion card", "course", "An expansion card is a flight card at the edge of the envelope. It extends the design claim beyond the center case, usually after a center-of-envelope sortie has passed. 'Center', 'corner', and 'expansion' are the three envelope settings.", "", "", "Course Topic Guide, Chapter 23", aliases=("expansion card", "Expansion", "envelope", "Corner of the envelope", "Center of the envelope"), ch=(23,))
g("Harness", "course", "A harness is the software that turns a model into an agent. It supplies the loop, the tools, the permissions, and the context assembly. Claude Code, Codex, and OpenCode are vendor harnesses. The files the student writes to steer one are the student's harness (Figure 17).", "'Harness engineering' is the 2025–26 term for building this layer deliberately.", "The Final System is a harness plus proof that it can build something.", "Course Topic Guide, Chapters 8, 9, 14", aliases=("harness", "harnesses", "harness engineering", "Harness engineering", "Meta-harness", "meta-harness"), ch=(8, 14))
g("V.I.B.E.S.", "course", "V.I.B.E.S. stands for Velocity Increased, Bugs Expected Software. It is gzkit's term for the failure class in which generation speed outruns verification.", "", "", "Course Topic Guide, Appendix D", aliases=("VIBES", "V.I.B.E.S"))
g("Nine agent failure modes", "course", "The nine agent failure modes are gzkit's catalogue, sourced to frontier system cards. The modes are safeguard circumvention, reckless action, fabrication, skipped cheap verification, correction fails, dishonest when caught, hallucinated authorization, security shortcut, and metagaming the gate. Each has a red-team probe in Appendix C.", "", "The decks cite the modes by number (#3 fabrication, #9 metagaming).", "Course Topic Guide, Appendix C", aliases=("Appendix C", "App. C", "failure modes", "nine modes"), ch=(20,))
g("Summary laundering", "course", "Summary laundering is a human-side failure in which a model's summary of the evidence is treated as the evidence itself. In gzkit's May 2026 incident, summaries ten subagents deep became 'facts' that nobody had checked.", "The term is the course's, listed with the human-side patterns in Appendix C.", "E9's planted-falsehood lab reproduces this failure at the smallest scale.", "Course Topic Guide, Appendix C and Appendix G", aliases=("laundering",), ch=(18,))
g("HandoffResult", "course", "A HandoffResult is the typed claim a worker returns to the controller. It carries a status from a closed set (DONE, DONE_WITH_CONCERNS, NEEDS_CONTEXT, BLOCKED), the files changed, and the evidence (the test command and its exit code). The controller rejects anything that does not parse, and there is no default branch that returns DONE.", "gzkit ADR-0.18.0 is the source. The field names are the course's own.", "E8's first rule is that a worker's result is a typed claim, and this is the type.", "E8 lecture, slide 7", aliases=("DONE", "DONE_WITH_CONCERNS", "NEEDS_CONTEXT", "BLOCKED", "dispatch record", "dispatch records"), ch=(17,))
g("ReviewResult", "course", "A ReviewResult is the typed verdict a reviewer returns. It carries PASS, FAIL, or CONCERNS, findings that each cite a location (file:line, test id, diff hunk), and a list of what the reviewer checked. FAIL and CONCERNS need a finding, and the controller rejects a verdict with no citations as malformed.", "gzkit ADR-0.18.0 is the source. The field names are the course's own.", "E8's second rule is that a verdict counts only if it cites evidence and its author could not edit the code.", "E8 lecture, slide 7", aliases=("PASS", "FAIL", "CONCERNS", "verdict", "ReviewResults"), ch=(17,))
g("Controller, worker, reviewer", "course", "Controller, worker, and reviewer are the three roles in the division of labor the course builds in E8. The controller dispatches one task. The worker (also called the implementer) returns a HandoffResult. The reviewer, which cannot edit, returns a ReviewResult. The controller merges only on PASS. The same division is plan, do, check, and it has appeared under one label or another since FIPA.", "", "", "E8 lecture; Figure 09", aliases=("controller", "worker", "reviewer", "implementer", "plan, do, check", "Plan, do, check"), ch=(17,))
g("Persona (traits, anti-traits)", "course", "A persona is a role specification the student can test. It states one job, observable traits ('cites file and line for every finding'), anti-traits ('does not rewrite the code it reviews'), and the why (what breaks if the role fails). A line such as 'You are a world-class senior engineer' is deleted on sight, because nothing in it can be tested.", "", "The anti-trait explains the rule to the model, and the permission deny makes the harness enforce it. Both, in that order.", "E8 lecture, slide 6", aliases=("persona", "personas", "anti-traits", "anti-trait"), ch=(17,))
g("Exceptional", "course", "Exceptional is the tier above a strong pass on a sortie. The flight card states an extra, harder design claim for it (two-stage review, a calibrated judge that survives injection, the removal that turns exactly the predicted cases red).", "", "", "Course Topic Guide, Chapter 23", aliases=("Exceptional mark",))
g("Route A / Route B", "course", "Route A and Route B are the two toolkit routes a student can take. Route A is a subscription harness plus a small API budget. Route B is fully local, with Ollama and open-weight models sized to the hardware. Path A and Path B in the memory Evolution are a different pair: the embedding retriever (Ollama) and the word-overlap retriever.", "", "", "Course Topic Guide, Appendix F", aliases=("Route A", "Route B", "Path A", "Path B"))
g("Judgment loop", "course", "The judgment loop is the closing form, carried over from CIDM 6330, that ends chapters and Teardowns. It states the decision, the characteristics the decision privileged, the cost, the failure mode, and the preservation mechanism.", "", "", "Course Topic Guide, Conventions", aliases=("judgment loop", "preservation mechanism", "Preservation"))
g("Tree Hollow", "course", "Tree Hollow is the Sprint and Drift essay that opens the course. Its stake is that a system can produce an answer without being able to answer for it.", "sprintanddrift.substack.com", "It is the first reading of E0.", "https://sprintanddrift.substack.com")

# ---------------- gzkit ----------------
g("gzkit", "course", "gzkit is the GovZero Kit, the course's reference design. It is a pip-installable governance toolkit with a ledger, gates, lanes, briefs, attestations, receipts, and a controller–worker pipeline. It is the one system for which the course has the entire record, including what went wrong (Appendix G, the incident casebook).", "Work on it started in January 2026. It descends from GovZero, with lineage from GitHub's spec-kit and the CLAUDE.md conventions.", "Every chapter's 'Reference design' section shows what gzkit did about that chapter's problem.", "gzkit.org; github.com/tvproductions/gzkit", aliases=("GovZero", "gz", "gz status", "gz arb red", ".gzkit"), ch=(25,))

# ---------------- harness: vendor harnesses and their parts ----------------
g("OpenCode", "harness", "OpenCode is the open-source terminal coding agent the course uses as its harness. It provides a TUI, a loop, built-in tools (read, edit, shell, webfetch), built-in agents (build, plan, general, explore, scout), permissions, skills, custom agents, commands, MCP, and plugins. AGENTS.md is its rules file.", "Anomaly (the former SST team) launched it in June 2025. It is MIT-licensed and runs with any provider or model. The repository is github.com/anomalyco/opencode.", "It is the middle ring of Figure 17, and students build their harness on it.", "https://opencode.ai/docs/", aliases=("opencode", "OpenCode Go", "OpenCode Zen", "Zen", "Go", "Big Pickle", "opencode/big-pickle", "TUI", "opencode.json"), ch=(14,))
g("Claude Code", "harness", "Claude Code is Anthropic's agentic coding tool. It is a terminal harness with tools, permissions, hooks (SessionStart, UserPromptSubmit, PreToolUse, PostToolUse, PreCompact, Stop, SessionEnd, and more), subagents in .claude/agents/, skills, and CLAUDE.md as its rules file. The Claude Agent SDK exposes the same loop to programs.", "Anthropic released it as a research preview in February 2025 and made it generally available in May 2025.", "It is the Teardown subject for subagents and hooks. The hook names on the E3 and E6 slides are Claude Code's.", "https://code.claude.com/docs", aliases=("CLAUDE.md", "Claude Agent SDK", "SessionStart", "PreToolUse", "PostToolUse", "PreCompact", "UserPromptSubmit", "SessionEnd", "Claude Code subagents", "subagent", "subagents", "Subagents"), ch=(8,))
g("Codex", "harness", "Codex is OpenAI's family of coding agents. Codex CLI is an open-source terminal agent (April 2025), and the cloud Codex agent runs tasks in sandboxes (May 2025). AGENTS.md began as Codex's rules-file convention.", "", "The course uses it as a second vendor harness for comparison, and its 'background agent' form is the survey subject of E9 through E12.", "https://openai.com/codex/", aliases=("Codex CLI", "Codex cloud", "OpenAI Agents SDK"), ch=(8, 9))
g("Cursor", "harness", "Cursor is an AI code editor (a fork of VS Code) with an agent mode, rules files in .cursor/rules, and its own background agents.", "Anysphere has developed it since 2023.", "It is one of the harnesses in the E8 and E9 feature comparisons.", "https://cursor.com", aliases=(".cursor/rules",))
g("GitHub Copilot", "harness", "GitHub Copilot is GitHub's AI pair programmer. It began as inline completion (2021), added an agent mode (February 2025), and added a cloud coding agent that works on a branch and opens pull requests (May 2025, renamed the cloud agent in April 2026).", "", "", "https://github.com/features/copilot", aliases=("Copilot",))
g("Gemini CLI", "harness", "Gemini CLI is Google's open-source terminal agent for Gemini models.", "Google released it in June 2025.", "It is one of the harnesses compared in the 2025 survey.", "https://github.com/google-gemini/gemini-cli")
g("AGENTS.md", "harness", "AGENTS.md is a plain Markdown file at the repository root that the harness loads into every turn. It states what the system is, what it must never do, the commands to run, and where things live. OpenCode reads it, with CLAUDE.md as a fallback. The course caps it at 4,000 characters, following gzkit ADR-0.0.54: a map, not an encyclopedia.", "It began as the Codex convention in 2025, and agents.md documents the cross-vendor format.", "It is drawer one in Figure 14. The first probe of an exercise asks whether the model answers from it.", "https://agents.md; https://opencode.ai/docs/rules/", aliases=("agents.md", "rules file", "instruction file", "instruction files"), ch=(14, 15))
g("Skills", "harness", "A skill is a folder with a SKILL.md file, which holds frontmatter (name, description) and a procedure. The harness shows the model only the name and description on each turn and loads the body when the model calls the skill tool. This arrangement is called progressive disclosure. In OpenCode, skills live in .opencode/skills/<name>/.", "Anthropic published Agent Skills in October 2025, and OpenCode supports the same layout.", "Skills are drawer three in Figure 14, and Figure 15 follows one from disk to the turn in which it runs.", "https://opencode.ai/docs/skills/; Anthropic, 'Equipping agents for the real world with Agent Skills' (2025)", aliases=("skill", "SKILL.md", "Agent Skills", "skill tool", "progressive disclosure"), ch=(14,))
g("Hooks", "harness", "A hook is code the harness runs at an event in the loop: before and after a tool call, at session start, or before compaction. Claude Code's hooks are SessionStart, PreToolUse, PostToolUse, and PreCompact. OpenCode's are plugin hooks such as tool.execute.before. A hook is a mechanism in the loop.", "", "E3 uses hooks to run checks before and after every tool call, and E10 puts the student's first gate in one.", "https://opencode.ai/docs/plugins/; Claude Code hooks reference", aliases=("hook", "plugin", "plugins", "tool.execute.before"), ch=(12,))
g("Permissions", "harness", "Permissions are the harness's gate on tool calls. Each tool and pattern (edit, shell, webfetch, skill, task) is set to allow, ask, or deny. In OpenCode they live in opencode.json and can be overridden per agent. A reviewer with edit: deny cannot fix the code it judges, whatever its prompt says.", "", "E3's point is that the harness enforces the gate; the gate is not requested of the model.", "https://opencode.ai/docs/permissions/", aliases=("permission", "permission gate", "edit: deny", "ask on bash"), ch=(12,))
g("Compaction", "harness", "Compaction is what the harness does when the context window fills. The model writes a summary of the history, and the summary replaces the history. It is the middle ring's own answer to a finite window. The student did not write the summary and cannot review it before it replaces the history.", "", "E6's budget record and the handoff file exist because compaction loses what the model thought mattered.", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("compaction", "compacted"), ch=(15,))
g("Context window", "harness", "The context window is the text the model reads on one call: the system prompt, the rules file, the tool list, the skill index, the history, and whatever memory adds. The harness rebuilds it every turn. It has a budget, because the more tokens it holds, the less reliably the model attends to any one of them.", "", "E6 treats the window as an engineered artifact with a budget (Figure 07).", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("context", "window", "the window", "attention budget", "Context engineering", "context engineering"), ch=(15,))
g("Handoff", "harness", "A handoff is a document that one session writes for the session that follows it. It records what was done, what is still open, and where the current truth lives. It costs one file, and the model that writes it is the model about to lose its context, so the document preserves what that model thought mattered.", "", "Students build the handoff in E6. Figure 14's table lists it as the weakest of the memory strategies, and as the most common.", "Course Topic Guide, Chapter 15", aliases=("handoff", "handoff.md", "Handoffs", "handoffs"), ch=(15,))
g("Memory layer (recall.py)", "harness", "The memory layer is the course's local memory. Its store is memory.jsonl, a file of dated records that each carry a source file and a retain_until date. A retriever scores the records against a question and injects the hits as a block marked 'data, not instructions'. An evict command removes expired records, and a ledger records every add, recall, and evict.", "Students build it in E7's lab.", "Figure 08 and Figure 14 state the rule: memory is a claim with a date, and the loop does not open the drawer by itself.", "CIDM6333_Lab_E7_Memory handout", aliases=("recall.py", "recall", "memory.jsonl", "memory-ledger.jsonl", "retain_until", "evict", "retriever", "Retention", "retention rule"), ch=(16,))
g("Tool", "harness", "A tool is a function the model can call by name with typed arguments. It has a schema (the contract), a side-effect class (read, write, or destructive), and a permission that gates the call. The harness treats the model as an untrusted caller: the harness runs the tool and returns the result into the next window.", "Function calling arrived in the OpenAI API in June 2023, and the MCP tool primitive generalized it.", "E3 treats tools as contracts, and Figure 04 plays one call through model, harness, gate, human, tool, and ledger.", "Course Topic Guide, Chapter 12", aliases=("tools", "Tools", "tool call", "function calling", "custom tool", "custom tools", "side-effect class"), ch=(12,))

# ---------------- protocols and standards ----------------
g("MCP", "protocol", "The Model Context Protocol is a client–server protocol over JSON-RPC. A host (the harness) connects clients to servers, and each server exposes three primitives, tools, resources, and prompts, under capabilities the two sides negotiate. Because one server serves every client, N×M integrations become N+M.", "Anthropic released it in November 2024. The decks follow its 2025–26 revisions (Streamable HTTP, OAuth-based authorization, a stateless core) and its donation to the Linux Foundation's Agentic AI Foundation in December 2025.", "E4 builds a server, and E5 covers its security and trust boundaries (Figure 05, Figure 06).", "https://modelcontextprotocol.io", aliases=("Model Context Protocol", "MCP server", "MCP servers", "GitHub MCP", "host", "hosts", "Streamable HTTP", "FastMCP", "Python SDK", "server registry", "elicitation"), ch=(13, 14))
g("JSON-RPC", "protocol", "JSON-RPC is a lightweight remote-procedure-call format in JSON (version 2.0, 2010). A request carries a method, params, and an id, and a response carries a result or an error.", "", "MCP's messages are JSON-RPC 2.0.", "https://www.jsonrpc.org/specification", aliases=("JSON-RPC 2.0",))
g("JSON Schema", "protocol", "JSON Schema is a vocabulary for describing the shape of JSON data (its types, required fields, and enums). Tool argument schemas, HandoffResult, and ReviewResult are JSON Schema in spirit, and Pydantic and Zod generate it from typed code.", "", "A closed status enum in the schema makes a result parse fail-closed, because a status outside the enum fails validation instead of passing through.", "https://json-schema.org", aliases=("schema", "schemas", "Pydantic", "Zod"))
g("OAuth 2.1 and PKCE", "protocol", "OAuth 2.1 is the authorization framework that MCP's remote transport uses. A client obtains a scoped token from an authorization server, and PKCE (Proof Key for Code Exchange) binds the authorization code to the client that requested it. The scope limits what the token may do.", "OAuth 2.1 consolidates OAuth 2.0 and its best practices, and PKCE is RFC 7636 (2015).", "E5 walks through the five-step authorization flow (Figure 06).", "https://modelcontextprotocol.io (authorization)", aliases=("OAuth", "PKCE", "scope", "PAT"), ch=(14,))
g("A2A", "protocol", "The Agent-to-Agent protocol lets one agent delegate work to another. An agent publishes an Agent Card (its identity, skills, endpoints, and auth requirements). A client agent sends it a Task, which moves through the states submitted, working, input-required, and completed, and returns Artifacts. A2A delegates work to somebody else's agent, whereas MCP gives tools to your own agent.", "Google published it in April 2025 and donated it to the Linux Foundation in June 2025. Version 0.3 (mid-2025) added signed Agent Cards and gRPC, v1.0 arrived in March 2026, and the protocol joined the Agentic AI Foundation in August 2026.", "E5 sets A2A against MCP, and E9 uses its delegation model.", "https://a2a-protocol.org", aliases=("Agent Card", "Agent-to-Agent", "A2A v1.0"), ch=(14, 18))
g("AP2", "protocol", "The Agent Payments Protocol is Google's extension for payments that an agent initiates. It is built on signed 'mandates' that record what the human authorized the agent to buy.", "Google, September 2025.", "E9 uses it as the example of a contract that a marketplace of agents would need.", "https://ap2-protocol.org", aliases=("mandates",), ch=(18,))
g("OWASP", "protocol", "The Open Worldwide Application Security Project publishes two threat lists the course uses. The OWASP Top 10 for LLM Applications (2025 list, codes LLM01–LLM10) covers prompt injection, improper output handling, excessive agency, unbounded consumption, and six more. The Agentic Top 10 (December 2025, codes ASI01–ASI10) does the same for agentic systems.", "", "The two lists are the threat vocabulary of E5, E7, and E11, and the decks cite them by code.", "https://genai.owasp.org", aliases=("OWASP Top 10", "Agentic Top 10", "ASI01", "ASI06", "ASI08", "LLM01", "prompt injection", "tool poisoning", "Injection", "injection"), ch=(14, 20))
g("OpenAPI", "protocol", "OpenAPI (formerly Swagger) is the standard description format for HTTP APIs. Several 2023 tool systems derived their tool schemas from OpenAPI documents, and MCP replaced that practice with its own tool listing.", "", "", "https://www.openapis.org", aliases=("REST", "HTTP"))

# ---------------- systems, frameworks, and companies ----------------
g("FIPA", "system", "The Foundation for Intelligent Physical Agents was a 1996 consortium that standardized multi-agent systems. Its agent communication language requires every message to carry a performative (inform, request, propose, refuse), and its interaction protocols include the contract net. FIPA became an IEEE Computer Society standards committee in 2005, and the IEEE and archived copies now host the specifications rather than fipa.org.", "FIPA was founded in 1996 and has been part of the IEEE since 2005.", "E8 takes FIPA as its baseline: a message type is a claim type, and FIPA had that thirty years before the chat transcript.", "https://www.fipa.org", aliases=("performative", "performatives", "FIPA-ACL"), ch=(4,))
g("Contract net", "system", "The contract net is Reid Smith's 1980 protocol for distributing tasks among agents. A manager announces a task, contractors bid, the manager awards the task, and the contractor reports a result or a failure. It is the first plan-do-check protocol with typed messages.", "Smith, 'The Contract Net Protocol' (IEEE Transactions on Computers, 1980).", "It is the first row of E8's 'under every name' table.", "Smith (1980)", aliases=("Contract net (Smith; FIPA)", "contract net"), ch=(4,))
g("BDI", "system", "Belief–Desire–Intention is an agent architecture in which an agent holds beliefs about the world, desires (its goals), and intentions (the plans it has committed to), and reconsiders its intentions when its beliefs change. Bratman's philosophy of intention (1987) became an agent architecture in Rao and Georgeff's work.", "Rao & Georgeff, 'BDI Agents: From Theory to Practice' (ICMAS-95).", "The course reads BDI for what LLM agents carried forward (goal decomposition, and halting as 'intention achieved or dropped') and for what they dropped (an inspectable belief state).", "Rao & Georgeff (1995)", aliases=("Belief–Desire–Intention", "BDI agents"), ch=(4,))
g("PEAS", "system", "PEAS stands for Performance measure, Environment, Actuators, and Sensors. It is Russell and Norvig's frame for specifying an agent's task before designing the agent.", "Russell & Norvig, Artificial Intelligence: A Modern Approach.", "Chapter 2 starts from PEAS and ends at the nine components.", "Russell & Norvig, AIMA", aliases=("Russell", "Norvig", "AIMA"), ch=(2,))
g("ReAct", "system", "ReAct (Reasoning and Acting) is a prompting pattern in which the model alternates a thought, an action (a tool call), and an observation (the tool's result) until it answers. It was the first widely copied form of the agent loop.", "Yao et al., 'ReAct: Synergizing Reasoning and Acting in Language Models' (2022; ICLR 2023).", "E1's loop is ReAct with a halt condition and a ledger added.", "https://arxiv.org/abs/2210.03629", aliases=("Yao",), ch=(5,))
g("Chain-of-thought", "system", "Chain-of-thought prompting asks a model to write intermediate reasoning steps before its answer, which improves multi-step accuracy on large models. Tree of Thoughts (2023) generalizes the single chain to a searched tree.", "Wei et al. (2022); Yao et al., 'Tree of Thoughts' (2023).", "E1 presents it as the step from prompting to programs.", "https://arxiv.org/abs/2201.11903", aliases=("CoT", "Tree of Thoughts", "ToT", "chain-of-thought"), ch=(5,))
g("Toolformer", "system", "Toolformer is a 2023 Meta paper in which a model teaches itself when to call tools (a calculator, search, a calendar). The model inserts API calls into text and keeps the calls that reduce loss.", "Schick et al. (2023).", "It is one of the 2023 'tools' systems in Chapter 6.", "https://arxiv.org/abs/2302.04761", ch=(6,))
g("Reflexion", "system", "Reflexion is an agent that keeps verbal self-reflections on its failed attempts in an episodic memory and reads them on the next attempt. In the course's terms, each stored reflection is a claim about what went wrong.", "Shinn et al. (2023).", "E7's survey of memory designs covers it.", "https://arxiv.org/abs/2303.11366", ch=(6, 16))
g("Generative Agents", "system", "Generative Agents is the 2023 Stanford 'Smallville' paper. Twenty-five agents live in a simulated town with a memory stream, retrieval scored by recency, importance, and relevance, and periodic reflection. It is the reference design for retrieval-scored memory.", "Park et al. (2023).", "Figure 08's pipeline (chunk, represent, store, score, inject) is this paper's pipeline.", "https://arxiv.org/abs/2304.03442", aliases=("Smallville", "Park"), ch=(6, 16))
g("MemGPT / Letta", "system", "MemGPT (2023) treats the context window like RAM and an external store like disk, and the model pages memory in and out through tools. Letta is the company and the framework that grew out of the paper.", "Packer et al. (2023).", "E7's survey uses it as the case of memory management treated as an operating-system problem.", "https://arxiv.org/abs/2310.08560", aliases=("MemGPT", "Letta"), ch=(16,))
g("RAG", "system", "Retrieval-Augmented Generation retrieves the documents relevant to a query, puts them in the prompt, and generates from them. The 2020 paper gave the pattern its name.", "Lewis et al. (2020).", "Every memory layer in the course is a RAG loop over its own records.", "https://arxiv.org/abs/2005.11401", aliases=("Retrieval-Augmented Generation", "embedding", "embeddings", "embeddinggemma"), ch=(16,))
g("AutoGPT", "system", "AutoGPT is the open-source project of March 2023 that ran GPT-4 in a loop with a goal, tools, and a file-based memory, and went viral. It had autonomy without a halt condition, so it looped, spent, and rarely finished.", "Toran Bruce Richards, 2023.", "E1 uses it as the example of the loop without a halt.", "https://github.com/Significant-Gravitas/AutoGPT", ch=(6,))
g("BabyAGI", "system", "BabyAGI is Yohei Nakajima's task-management loop of March 2023. The loop creates tasks, prioritizes them, executes them, and repeats. Its few hundred lines defined the 'autonomous agent' shape of 2023.", "Yohei Nakajima, March 2023.", "Chapter 6 reads it beside AutoGPT as a 2023 loop with a goal and no grounding, budget, or evaluator.", "https://github.com/yoheinakajima/babyagi", ch=(6,))
g("CAMEL", "system", "CAMEL (Communicative Agents for 'Mind' Exploration) has two role-playing models, an AI user and an AI assistant, solve a task by chatting, with inception prompts that fix their roles. There is no checker, and the assistant ends the task by emitting a token.", "Li et al. (NeurIPS 2023).", "E8 uses it as the example of roles assigned by prompt alone.", "https://arxiv.org/abs/2303.17760", ch=(6, 17))
g("MetaGPT", "system", "MetaGPT is a multi-agent framework in which roles (product manager, architect, engineer, QA) pass structured documents (a PRD, a design, code) to one another, with executable feedback from running the code. The roles are connected by documents rather than by chat.", "Hong et al. (2023; ICLR 2024).", "E8 presents it as the step past CAMEL, with documents between the roles instead of chat.", "https://arxiv.org/abs/2308.00352", ch=(6, 17))
g("AutoGen", "system", "AutoGen is Microsoft's multi-agent conversation framework. An assistant agent and a user-proxy agent that runs code converse until one of them says TERMINATE.", "Wu et al. (2023).", "In AutoGen, roles are configuration.", "https://arxiv.org/abs/2308.08155", ch=(6, 17))
g("CrewAI", "system", "CrewAI is a Python framework in which each agent is defined by a role, a goal, and a backstory, and agents are organized into crews that run a sequential or a hierarchical process. In the hierarchical mode a manager agent reviews the work, and a task guardrail can return (bool, value).", "João Moura, 2023–24.", "", "https://docs.crewai.com", ch=(17,))
g("LangChain", "system", "LangChain is the 2022 library that packaged chains, tools, agents, and memory for LLM applications. LangGraph (2024) is its state-graph runtime, with nodes, edges, conditional routing, a checkpointer, and interrupt() for a human in the loop. LangSmith is its tracing and evaluation service.", "Harrison Chase, October 2022; LangGraph 2024.", "E2 argues that every framework is a theory of who owns the loop, and E8 uses LangGraph's supervisor pattern as a state graph with a human interrupt.", "https://www.langchain.com", aliases=("LangGraph", "LangSmith", "supervisor", "StateGraph", "interrupt()", "checkpointer"), ch=(11, 17))
g("Pydantic AI", "system", "Pydantic AI is a Python agent framework from the Pydantic team, with typed tool definitions, structured outputs validated by Pydantic models, and dependency injection.", "The Pydantic team, 2024 onward.", "The course's airline-operations testbed is built on it.", "https://pydantic.dev/docs/ai/overview/", ch=(11,))
g("Ollama", "system", "Ollama is a local model runner. It pulls open-weight models and serves them over an HTTP API on your machine, including an embeddings endpoint.", "", "It is Route B's substrate, and E3 and E7 require a local model on both routes.", "https://ollama.com", aliases=("local model", "open-weight"))
g("Langfuse", "system", "Langfuse is an open-source observability platform for LLM applications. It records traces, spans, costs, and evaluation runs.", "", "E11's examples of 'receipts over narrative' use trace waterfalls of this kind (Figure 12).", "https://langfuse.com", aliases=("trace", "traces", "span", "spans"), ch=(20,))
g("Anthropic", "org", "Anthropic is the company that makes Claude, Claude Code, and MCP. The course reads its engineering posts: 'Building Effective Agents' (December 2024), 'How we built our multi-agent research system' (June 2025), 'Effective context engineering for AI agents' (September 2025), 'Effective harnesses for long-running agents' (November 2025), the Agent Skills post (October 2025), and 'Demystifying evals for AI agents' (January 2026).", "", "E10 uses the vocabulary of the evals post (task, trial, grader, transcript, outcome).", "https://www.anthropic.com/engineering", aliases=("Building Effective Agents", "multi-agent research system", "Claude"))
g("OpenAI", "org", "OpenAI makes the GPT models, ChatGPT, function calling (June 2023), the Agents SDK, and Codex.", "", "Its 'A Practical Guide to Building Agents' (2025) is on the reading list.", "https://openai.com", aliases=("GPT-4", "ChatGPT", "o-series"))
g("Cognition", "org", "Cognition is the company behind Devin. Walden Yan's June 2025 post 'Don't Build Multi-Agents' argues that split workers make conflicting implicit decisions unless they share full traces. It is the published counter-argument to Anthropic's multi-agent research post of the same week.", "", "E8 weighs the two posts against each other.", "https://cognition.com/blog/dont-build-multi-agents", aliases=("Yan", "Devin"), ch=(17,))
g("Invariant Labs", "org", "Invariant Labs is the security group whose April 2025 'tool poisoning' demonstration hid instructions inside an MCP tool description, and the model followed them.", "", "The E5 lab reproduces the demonstration with a harmless canary.", "https://invariantlabs.ai", aliases=("canary",), ch=(14,))
g("Linux Foundation", "org", "The Linux Foundation is home to the Agentic AI Foundation, formed in December 2025 with MCP, goose, and AGENTS.md as founding projects. A2A was donated to the Linux Foundation in June 2025 and joined the Agentic AI Foundation in August 2026.", "", "Both protocols now sit under the foundation, so neither is governed by one vendor.", "https://www.linuxfoundation.org", aliases=("Agentic AI Foundation",))

# ---------------- benchmarks and evaluation ----------------
g("SWE-bench", "bench", "SWE-bench is a benchmark of 2,294 real GitHub issues from twelve Python repositories, on which an agent must produce a patch that passes the repository's tests. SWE-bench Verified (2024) is a human-validated subset of 500 tasks, now saturated at the frontier, and SWE-bench Pro (2025) is the harder successor. SWE-agent (2024) built the first strong agent-computer interface for the benchmark, and Agentless (2024) showed a pipeline with no agent competing with it.", "Jimenez et al. (2023); Yang et al. (2024); Xia et al. (2024).", "E10 asks what five agent benchmarks measure and what they hide.", "https://www.swebench.com", aliases=("SWE-agent", "Agentless", "SWE-bench Verified", "SWE-bench Pro"), ch=(7, 19))
g("HumanEval", "bench", "HumanEval is OpenAI's 2021 set of 164 hand-written Python programming problems with unit tests, scored by pass@k. It was the first standard code benchmark and is now largely saturated.", "Chen et al. (2021).", "", "https://arxiv.org/abs/2107.03374", aliases=("pass@k",), ch=(19,))
g("GAIA", "bench", "GAIA is a benchmark of real-world assistant questions that need browsing, tool use, and multi-step reasoning, each with an unambiguous answer. The questions are easy for humans and hard for agents.", "Mialon et al. (2023).", "It is in E10's set of five benchmarks.", "https://arxiv.org/abs/2311.12983", ch=(19,))
g("WebArena", "bench", "WebArena is a benchmark of tasks for web agents on self-hosted realistic websites (shopping, forums, code hosting).", "Zhou et al. (2023).", "E10 covers it among the five agent benchmarks.", "https://webarena.dev", ch=(19,))
g("ToolBench", "bench", "ToolBench is the dataset from ToolLLM ('Facilitating LLMs to Master 16000+ Real-world APIs', 2023), a benchmark for tool use over thousands of real APIs. Gorilla (2023) is the related Berkeley work on models that call APIs correctly.", "Qin et al. (2023); Patil et al. (2023).", "", "https://arxiv.org/abs/2307.16789", aliases=("Gorilla",), ch=(6, 12))
g("MT-Bench and Chatbot Arena", "bench", "MT-Bench and Chatbot Arena are LMSYS's 2023 evaluation work. MT-Bench is a set of multi-turn questions graded by a strong model, and Chatbot Arena collects crowd-sourced pairwise preferences. The paper gave LLM-as-a-judge its name and measured three of its biases: position, verbosity, and self-enhancement.", "Zheng et al., 'Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena' (NeurIPS 2023).", "E10's judge-bias table starts with this paper.", "https://arxiv.org/abs/2306.05685", aliases=("MT-Bench", "Chatbot Arena", "Zheng", "LLM-as-a-judge", "judge", "Judge"), ch=(19,))
g("Judge biases", "bench", "Judge biases are the errors a model makes when it grades another model. They include position bias (Wang et al. 2023, 'Large Language Models are not Fair Evaluators'), verbosity bias, self-preference (Panickssery, Bowman & Feng 2024 showed that models recognize their own outputs, and Wataoka et al. 2024 argue that the mechanism is familiarity), and injection (hidden text in an answer moves the score).", "", "E10's rule follows from these biases: a judge is admissible only if it comes from another model family and survives an injection.", "Wang et al. (2023) arXiv:2305.17926; Panickssery, Bowman & Feng (2024) https://arxiv.org/abs/2404.13076; Wataoka et al. (2024) arXiv:2410.21819", aliases=("Panickssery", "Wataoka", "self-preference", "position bias", "verbosity bias"), ch=(19,))
g("BLEU", "bench", "BLEU is the 2002 machine-translation metric that scores n-gram overlap between a candidate translation and the reference translations.", "Papineni et al. (2002).", "The 2017 Transformer paper reports its results in BLEU, and the mini lecture reads those tables.", "https://aclanthology.org/P02-1040/", ch=())
g("MAST", "paper", "MAST is the Multi-Agent System Failure Taxonomy from 'Why Do Multi-Agent LLM Systems Fail?'. It lists fourteen failure modes in three categories (specification and system design, inter-agent misalignment, and task verification and termination), with prevalence figures from annotated traces.", "Cemri et al. (2025).", "It is E9's taxonomy, and Figure 10's failure matrix is built on it.", "https://arxiv.org/abs/2503.13657", aliases=("Cemri", "Why Do Multi-Agent LLM Systems Fail"), ch=(18,))
g("Berkeley benchmark exploits", "paper", "The Berkeley benchmark exploits are a 2026 study in which the Berkeley RDI group broke agent benchmarks. Each exploit is a grader that trusted something the agent could touch (the answer file, the judge's prompt, the test harness). The blog post (April 2026) broke eight benchmarks, and the paper, 'Do Androids Dream of Breaking the Game? Systematically Auditing AI Agent Benchmarks with BenchJack' (May 2026), audits ten and reports 219 flaws.", "Wang, Mang, Cheung, Sen & Song, Berkeley RDI blog, April 2026; Wang, Mang, Cheung, Li, Sen & Song, arXiv:2605.12673, May 2026.", "The lesson for your own evals is to check that the agent cannot reach the answers.", "https://arxiv.org/abs/2605.12673", aliases=("Berkeley RDI", "BenchJack"), ch=(19,))
g("Transformer", "paper", "The Transformer is the 2017 architecture from 'Attention Is All You Need'. It replaces recurrence with scaled dot-product attention over queries, keys, and values (softmax of QK^T/sqrt(d) times V), uses multi-head attention, and stacks an encoder and a decoder with residual connections and layer normalization. Positions enter through sinusoidal encodings. The authors trained the model with Adam, dropout, and label smoothing, and they report its results in BLEU on the WMT newstest sets. Every model the course's harnesses call descends from it, and GPT (Radford et al., 2018) kept the decoder only.", "Vaswani et al. (2017).", "The mini lecture reads the paper as a design document.", "https://arxiv.org/abs/1706.03762", aliases=("Attention Is All You Need", "Vaswani", "attention", "softmax", "multi-head attention", "decoder-only"), ch=(1,))
g("Degani and Wiener", "paper", "Degani and Wiener's 'Philosophy, policies, procedures and practices: the four P's of flight-deck operations' argues that a procedure is only as good as the practice it produces, and that accidents occur in the gap between the two.", "Asaf Degani and Earl Wiener, chapter in Johnston, McDonald & Fuller (eds.), Aviation Psychology in Practice (Avebury, 1994; Routledge reissue 1997); the same framework is in NASA CR-177642, 'On the design of flight-deck procedures' (1994). Their 1997 IEEE paper, 'Procedures in complex systems: the airline cockpit,' is a separate work.", "The course's 'presence is not procedure' comes from this work.", "https://ntrs.nasa.gov/citations/19940029437", ch=(3,))
g("Nygard, Release It!", "paper", "Release It! is Michael Nygard's book on production software. It covers stability patterns (the circuit breaker, the bulkhead, timeouts), capacity, and operations. Nygard also wrote the ADR template the course uses.", "Release It! 2nd edition (2018).", "E12's circuit-breaker simulator and its rollback doctrine come from the book.", "Reading list, Appendix E", aliases=("Nygard", "circuit breaker"), ch=(21,))

# ---------------- methods and general terms ----------------
g("TDD / BDD", "method", "Test-Driven Development is the practice of writing the failing test before the code that makes it pass. Behavior-Driven Development writes the acceptance criteria as behaviors (given, when, then) that a test suite can check.", "", "The two practices are Gates 2 and 4 of the course's five gates.","Course Topic Guide, Chapter 3", aliases=("TDD", "BDD", "pytest", "uv run pytest"), ch=(3, 19))
g("Golden set", "method", "A golden set is a fixed set of inputs with known-good outputs that the evaluation runs against every change. The regression delta is the difference between the baseline run and the candidate run, and the gate turns red when the delta crosses the threshold you pre-registered.", "", "E10 builds one (Figure 11), because one run is an anecdote.","Course Topic Guide, Chapter 19", aliases=("golden.jsonl", "regression delta", "delta gate", "baseline"), ch=(19,))
g("Red team", "method", "A red team probes its own system the way an adversary would and records what the system did. In this course the nine failure modes of Appendix C are the probe list.", "", "E11's lab plants falsehoods and injections and then reads the traces.","Course Topic Guide, Chapter 20", aliases=("red-team", "Red Team", "adversary", "second-family adversary"), ch=(20,))
g("Lock with a TTL", "method", "A lock with a TTL is a mutual-exclusion token that expires. A worker that holds the lock on a file or a task must renew it before the Time To Live runs out or lose it, so a crashed worker cannot block the others forever.", "", "E9's build uses one to coordinate parallel workers.","Course Topic Guide, Chapter 18", aliases=("TTL", "lock", "locks"), ch=(18,))
g("Rollback", "method", "A rollback returns a deployed system to its previous release, and the rollback itself is recorded in the ledger.", "", "E12's claim is that the way back works before the way forward is used.","Course Topic Guide, Chapter 21", aliases=("rollback", "code freeze", "Release"), ch=(21,))
g("JSONL", "method", "JSON Lines is a text format with one JSON object per line, which makes a file easy to append to and to read one record at a time.", "", "The ledger, memory.jsonl, and golden.jsonl all use it.","https://jsonlines.org", aliases=("jsonl",))
g("SHA-256", "method", "SHA-256 is a cryptographic hash function. It turns a file or a string into a fixed-length fingerprint that changes if any byte of the input changes.", "", "Receipts carry one, the golden set is pinned by one, and Figure 06's hash-pin check guards a tool description with one.","", aliases=("sha256", "hash", "hash-pin"))
g("Workflow versus agent", "method", "Anthropic's 2024 engineering post distinguishes a workflow, in which code fixes the sequence of model calls and tool calls in advance, from an agent, which decides its own next step inside a loop. The post lists five workflow patterns (prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer) before it reaches the agent.", "Anthropic, 'Building Effective Agents' (December 2024).", "E2 and Figure 03 use the distinction to ask who owns the loop, the code or the model.","https://www.anthropic.com/engineering/building-effective-agents", aliases=("workflow", "workflows", "five patterns", "orchestrator-workers", "evaluator-optimizer"), ch=(11,))
g("Agentic AI", "method", "Agentic AI is the stage in the course's five-stage progression (foundation, creation, core systems, action, full automation) at which a model perceives, reasons, plans, and acts on an environment through tools, in a loop that has a halt condition. As the term is used in this book, an agent is a system whose reasoner is a language model and whose loop halts.", "", "E0 draws two maps: the seven-layer stack and the five-stage progression.","Course Topic Guide, Chapters 1 and 2", aliases=("agent", "Agent", "agents", "halt", "halt condition", "Halt", "loop", "the loop", "agent loop"), ch=(1, 2))
g("LLM", "method", "A large language model is a transformer trained on text to predict the next token, and a program reaches it through a chat or completion API. It is the inner ring of Figure 17: one window goes in, one answer comes out, and nothing is kept between calls.", "The transformer architecture dates from Vaswani et al. (2017).", "","", aliases=("language model", "model", "token", "tokens"))
g("SDK / API / CLI", "method", "A Software Development Kit is a library for building on a service (the Claude Agent SDK, the OpenAI Agents SDK, the MCP Python SDK). An API is the HTTP interface itself, and a CLI is a command-line program that a person runs in a terminal.", "", "The course treats an SDK as the harness's loop exposed to your code.","", aliases=("SDK", "SDKs", "API", "CLI"))

# ---------------- additions from the Oct 22 lecture-gap audit ----------------
g("OpenCode models: Big Pickle, Zen, Go", "harness", "In this course a model reaches OpenCode in one of three ways. Big Pickle is OpenCode's free model on the Zen gateway, a model of undisclosed family with an unpublished context window, offered at no charge with the caveat that data from the free period may be used for training. OpenCode Zen is the gateway's set of models whose families are disclosed. OpenCode Go is the paid tier ($10 a month as of fall 2026), with dollar limits per five hours, per week, and per month. Route B students use Ollama instead.", "", "Every exercise states which model it runs on, and the cost tables in E6 and E9 are computed against these tiers.","https://opencode.ai/docs/zen/; https://opencode.ai/docs/go/", aliases=("Big Pickle", "opencode/big-pickle", "OpenCode Zen", "OpenCode Go", "Zen gateway"))
g("System card", "paper", "A system card is the evaluation report a lab publishes with one model release. It states what was tested and how, the residual failure rates, the safety level the model ships under, and the behaviors seen in red-teaming.", "Anthropic, OpenAI, and Google DeepMind each publish them.", "Appendix C's nine failure modes are sourced to frontier system cards, and E11 reads two of them as Design Analyses.","https://www.anthropic.com/system-cards; https://openai.com/safety/", aliases=("system cards", "frontier system cards", "ASL-3"), ch=(20,))
g("Guardrail", "course", "A guardrail is a mechanism at an enforcement locus that refuses an action whatever the model has decided (a permission deny, a server-side scope check, a hook, a commit-time diff check). A sentence in a prompt asks the model to refrain and cannot itself refuse, so the course does not count it as a guardrail.", "", "E11's attack cards each state the guardrail under test, because the course's test of any safety claim is where the check runs and whether it can say no.","Course Topic Guide, Chapter 20", aliases=("guardrails",), ch=(12, 20))
g("Enforcement locus", "course", "An enforcement locus is the place in the pipeline where a check runs and can refuse. The course distinguishes three: at the call (a schema or a hook), at the effect (a commit-time diff, git diff --cached), and at the door (release).", "gzkit moved its write fences from the call to the commit locus after the August 2026 hook incident, in which a hook never saw the write it was guarding.", "","Course Topic Guide, Chapters 12 and 20; Appendix G", aliases=("commit locus", "enforcement loci"), ch=(12, 20))
g("Incident casebook (Appendix G)", "course", "Appendix G is gzkit's dated record of its own failures from January to August 2026. It includes the first repudiated attestation (June 13), four briefs attested Completed for code that did not exist (June 16), the ten-deep subagent chain whose summaries became facts (May 24), the stale-clone handoff (April 26), the hook that never saw the write (August 21–23), and the marker-file gate (August 21).", "", "Every 'reference design' slide draws on it. The course argues that these failures are ordinary, and the argument rests on having the receipts for them.","Course Topic Guide, Appendix G", aliases=("Appendix G", "casebook", "incident casebook"), ch=(9,))
g("Marker-file gate (presence is not procedure)", "course", "In the gzkit incident of August 21, 2026, a pipeline gate checked only that a marker file was present, and a stale marker licensed about 350 lines of change with no dispatch and no review. The rule gzkit wrote afterward is that a presence check says 'armed' and never 'ran', so a gate must read the record of the run.", "", "","Course Topic Guide, Appendix G", aliases=("presence is not procedure", "marker file", "undispatched Stage 2"), ch=(9, 19))
g("Trust doctrine (T0–T3)", "course", "The trust doctrine is gzkit's assignment of a trust tier to every kind of input. T0 is the operator's own words, T1 is repository canon, T2 is tool and command output, and T3 is anything a model wrote or fetched. Trust-chain poisoning is the failure in which each layer accepts the layer below as fact, so that no single step is wrong and the conclusion at the top is.", "gzkit's April 18, 2026 outage is the casebook example of trust-chain poisoning.", "","https://gzkit.org/governance/trust-doctrine/", aliases=("trust doctrine", "trust-chain poisoning", "trust tier"), ch=(20,))
g("MX mode", "course", "MX mode is gzkit's maintenance posture after the June 2026 audit (ADR-0.0.74), stated as 'loose in the bay, hard at the door.' Work in progress may be untidy, and every gate holds at the release door. The MX hangar is the branch where that work happens.", "", "","Course Topic Guide, Chapter 21; Appendix G", aliases=("MX hangar", "loose in the bay"), ch=(21,))
g("DO IT RIGHT rules", "course", "DO IT RIGHT is the rule set gzkit adopted after the ten-deep chain of May 24, 2026. No summary is a fact until its source is read. Every delegated result states what it read and what it ran. A subagent's report is T3 until a human or a test confirms it.", "", "The rules answer summary laundering, the failure in which a subagent's summary is passed upward as fact.","Course Topic Guide, Appendix G", aliases=("ten-deep chain",), ch=(18,))
g("Canary", "method", "The course uses the term in two ways. In E5 a canary is a harmless payload planted in a tool description to show that the model follows hidden instructions (the Invariant Labs demonstration). From E11 on it is a planted fake secret string that the builder searches for in images, logs, and commits to prove that a leak path exists, and E12's release gate greps for it.", "", "","Course Topic Guide, Chapters 14, 20, 21", aliases=("canary string", "canary payload"), ch=(14, 20, 21))
g("Pre-registration", "method", "Pre-registration is the practice of writing the hypothesis, the measure, and the decision rule before collecting the data, so that the result cannot be fitted to the outcome. HARKing (hypothesizing after the results are known) is the failure it prevents.", "Nosek et al., 'The preregistration revolution' (PNAS, 2018); Kerr, 'HARKing' (1998).", "The flight card is pre-registration applied to a build, and E10's gate is pre-registered: the delta that turns it red is written down before the run.","https://www.pnas.org/doi/10.1073/pnas.1708274114", aliases=("pre-registered", "HARKing", "Nosek", "Kerr"), ch=(19, 23))
g("Attack card", "course", "An attack card is E11's pre-registered adversarial test. It states the objective (which is the falsifier), the failure-mode number it targets, the delivery path, the payload's SHA-256, the guardrail under test, and the expected observable. The Chase writes two of the five cards and seals them, so the builder cannot tune the system to them.", "", "","Course Topic Guide, Chapter 20", aliases=("attack cards", "sealed card"), ch=(20,))
g("Two-stage review", "course", "Two-stage review puts two reviewers with different questions in a fixed order, and neither may edit. The spec reviewer asks whether the change does what the brief asks and stays inside the allowed paths. The quality reviewer asks, only after a spec PASS, whether the change is done well. gzkit's four personas are implementer, spec reviewer, quality reviewer, and narrator.", "", "The order matters, because a quality review of the wrong feature returns a confident PASS.","E8 lecture, slide 8", aliases=("spec reviewer", "quality reviewer", "narrator", "spec review", "quality review"), ch=(17,))
g("Dispatch record", "course", "A dispatch record is gzkit's one record per role per task. It says who was dispatched, with what brief, and what came back. If there is no record, the role did not run, whatever the summary says: 'credit is never inferred.' A run with one agent declares itself with --single-driver --reason.", "gzkit ADR-0.18.0", "","https://gzkit.org/user/concepts/subagent-pipeline/", aliases=("dispatch records", "credit is never inferred", "single-driver"), ch=(17,))
g("Deployment vocabulary", "method", "E12 introduces these terms. FastAPI is the Python web framework the reference service runs on. A wheel is the binary package format that Python builds. Docker and Podman are container runtimes, and an image digest is the SHA-256 that identifies an exact image, where a tag can move. An idempotency key is a client-supplied id that lets a retried request be applied once. A runbook is the written procedure an operator follows for a release or an incident.", "", "","Course Topic Guide, Chapter 21", aliases=("FastAPI", "wheel", "Docker", "Podman", "image digest", "idempotency key", "runbook"), ch=(21,))
g("Stability patterns (Nygard)", "paper", "Nygard's Release It! collects stability patterns for production systems. The ones the course uses are Timeouts (never wait forever), Circuit Breaker (stop calling a failing dependency and let it recover), Steady State (a system must run indefinitely without human intervention), Fail Fast (reject early rather than consume resources), Governor (slow down automated actions so a human can intervene), and Force Multiplier (the dark side of automation, which amplifies a mistake across the fleet).", "Nygard, Release It! 2nd ed. (2018).", "E12 applies Governor and Force Multiplier to agents.","https://pragprog.com/titles/mnee2/release-it-second-edition/", aliases=("Timeouts", "Steady State", "Fail Fast", "Governor", "Force Multiplier"), ch=(21,))
g("Toolkit: uv, ruff, ty", "harness", "The course's Python toolkit comes from Astral. uv is the package and environment manager that every command runs through (uv run, uv python install 3.14). ruff is the linter and formatter, and ty is the type checker from the same team. VS Code is the assumed editor, and the GitHub Student Developer Pack supplies the subscriptions Route A uses.", "Astral (uv, ruff, ty).", "","https://docs.astral.sh/uv/", aliases=("uv", "ruff", "ty", "Student Developer Pack"))
g("Google ADK", "system", "Google's Agent Development Kit (2025) is a Python and Java framework with workflow agents (sequential, parallel, loop) and LLM agents, built to speak A2A natively.", "Google, 2025.", "The comparison tables in E0 and E2 include it.","https://google.github.io/adk-docs/", aliases=("Agent Development Kit", "ADK"), ch=(11,))
g("Spec-driven kits: spec-kit, OpenSpec, BMAD, GSD", "system", "Spec-driven kits put a written specification ahead of agent-generated code. The four the course compares are GitHub's spec-kit (2025), OpenSpec, BMAD (Breakthrough Method of Agile AI-Driven Development), and GSD.", "", "The orientation's comparison table and Chapter 8's 'spec-driven kits' section place gzkit among them: it shares lineage with spec-kit and adds the ledger, gates, and attestation that the others leave to the human.","https://github.com/github/spec-kit; https://gzkit.org/examples/comparison-gzkit-speckit-bmad/", aliases=("spec-kit", "OpenSpec", "BMAD", "GSD"), ch=(8,))
g("Computer use", "harness", "Computer use is the capability Anthropic released in October 2024 in which the screen is the tool. Perception is a screenshot, and every action (click, type, scroll) is write-class.", "Anthropic, October 2024.", "E3 uses it as the limiting case of a tool contract, since the schema is 'any pixel'.","https://www.anthropic.com/news/3-5-models-and-computer-use", aliases=("computer-use",), ch=(7, 12))
g("MAST categories FC1–FC3", "paper", "Cemri et al.'s taxonomy of multi-agent failures has three categories. FC1 is specification and system design (the task, role, or stopping condition was wrong). FC2 is inter-agent misalignment (agents talked past each other). FC3 is task verification and termination (nobody checked, or checked wrong). The paper reports prevalence by category from annotated traces.", "Cemri et al. (2025), v3.", "Summary laundering is FC2 and FC3 at once.","https://arxiv.org/abs/2503.13657", aliases=("FC1", "FC2", "FC3"), ch=(18,))
g("AI_LOG.md and LEDGER.md", "course", "Every course repository keeps two files. AI_LOG.md is the Sprint's attribution record of what was asked, which model answered, what was kept, what was rejected, why, and how it was verified. LEDGER.md (or ledger.jsonl) is the event log of sorties, verdicts, gates, and commits. The design-analyses/ directory holds the Design Analyses.", "", "The AI log is discussed in Drift, and the ledger is what the Chase reads.","Course Topic Guide, Chapters 22 and 23", aliases=("AI_LOG.md", "LEDGER.md", "AI log", "design-analyses/"), ch=(22, 23))
g("Course Topic Guide", "course", "The Course Topic Guide is the outline edition of the textbook, Answerable Systems. It has twenty-six chapters (Part I the posture, Part II the survey, Part III the build, Part IV the method) and appendices A–G.", "", "When a slide says 'chapter 16' or 'Appendix C', this is the book it means, and the chapter-to-Evolution map on its front page says which chapters each Evolution uses.","/textbook/", aliases=("textbook", "the book"), ch=())
g("OpenTelemetry", "protocol", "OpenTelemetry is the vendor-neutral standard for traces, metrics, and logs. A trace is a tree of spans, each with a start, an end, attributes, and a parent. OTLP is the wire protocol, and the GenAI semantic conventions define the attributes for model calls and tool calls. Langfuse and LangSmith ingest it.", "CNCF, 2019 onward.", "E11's receipts are spans, and Figure 12 is a span waterfall.","https://opentelemetry.io", aliases=("OTel", "OTLP", "span tree", "GenAI conventions"), ch=(20,))
g("MCP threat mechanisms", "protocol", "E5 covers four ways an MCP server can attack the model that calls it. Tool poisoning hides instructions in a tool description. The confused deputy is a server that acts on the user's authority for someone else's request. A rug pull is a tool description that changes after approval. Cross-server shadowing is one server's description instructing the model about another server's tools.", "Invariant Labs (April 2025) and the MCP security best-practices page.", "The defenses are hash-pinned descriptions (tool-pins.json), scoped tokens, and the rule that every description is untrusted content.","https://modelcontextprotocol.io/specification/draft/basic/security_best_practices", aliases=("confused deputy", "rug pull", "cross-server shadowing", "resource injection", "tool-pins.json"), ch=(14,))
g("Hollow test (hollow antibody)", "course", "A hollow test is a check that cannot fail. Examples are a test that compares the code with itself, an assertion with no input that could make it false, and a gate that looks for a file rather than a result. A live negative control (remove the feature and watch the test go red) is the cure.", "gzkit's June 2026 audit found that its own hollow-test detector was hollow (ADR-0.0.73).", "E10's Sortie 10 asks for the RED witness for this reason.","Course Topic Guide, Chapter 19", aliases=("hollow antibody", "hollow test", "tautological test", "live negative control", "@enforces"), ch=(19,))
g("τ-bench family", "bench", "τ-bench (Sierra, 2024) scores an agent on tool use with a simulated user in retail and airline domains. It introduced pass^k, the chance that k independent trials all succeed, which punishes inconsistency. τ²-bench (2025) adds a user who also acts on tools. AgentBench, CAR-bench, and FieldWorkArena are the other agent benchmarks E10 compares.", "Yao, Shinn, Razavi & Narasimhan (2024).", "E10 uses pass^k because one run is an anecdote and pass^k makes consistency the score.","https://arxiv.org/abs/2406.12045", aliases=("τ-bench", "tau-bench", "pass^k", "τ²-bench", "AgentBench"), ch=(19,))
g("Context rot and lost in the middle", "paper", "Two results concern long context windows. Liu et al. (2023), in 'Lost in the Middle', found that models use information at the start and end of a long context better than information in the middle. Chroma's 2025 'Context Rot' report found that performance degrades as input length grows, even on simple tasks.", "Liu et al. (2023); Chroma (2025).", "Both support E6's budget rule and the four compaction techniques (context editing, tool-result clearing, a keep list, re-seeding).","https://arxiv.org/abs/2307.03172", aliases=("Context Rot", "Lost in the Middle", "context editing", "tool result clearing"), ch=(15,))
g("AI governance frameworks", "org", "E0 situates the course against four bodies of regulation and standards: the NIST AI Risk Management Framework (2023), the EU AI Act (2024, in force in stages), ISO/IEC 42001 (the AI management-system standard, 2023), and the third-party audit literature (Raji et al., 'Outsider Oversight', 2022; Groves et al., 'Auditing Work', 2024).", "", "E0 argues that none of them reaches the engineer's desk and that index zero does.","https://www.nist.gov/itl/ai-risk-management-framework", aliases=("NIST AI RMF", "EU AI Act", "ISO/IEC 42001", "Raji", "Auditing Work"), ch=(3,))
g("Background and cloud agents", "harness", "Background and cloud agents run without a terminal open. The examples the course surveys are Codex cloud (sandboxed tasks that open pull requests), GitHub Copilot's cloud agent, Claude Code's cloud sessions and GitHub Action, and scheduled routines.", "", "E12's survey treats them as the same loop with the human further from index zero, which is why the release gates matter more for them.","Course Topic Guide, Chapter 9", aliases=("background agents", "cloud agent", "Codex cloud agent", "Claude Code GitHub Action", "routines"), ch=(9, 21))
g("Memory retrieval vocabulary", "method", "E7 introduces these terms. Bag-of-words and TF-IDF score a match by word overlap, which is auditable and blind to synonyms (recall.py's Path B). Embeddings and cosine similarity give each text a vector and score by the angle between vectors, which handles paraphrase and is not auditable (Path A, through Ollama's /api/embed with embeddinggemma, nomic-embed-text, or qwen3-embedding). A supersedes field is a record's pointer to the record it replaces. The memory kinds are episodic (what happened), semantic (what is true), procedural (how to), and working state (this session).", "", "","Course Topic Guide, Chapter 16", aliases=("TF-IDF", "bag-of-words", "cosine", "supersedes", "episodic", "semantic memory", "procedural memory", "nomic-embed-text", "all-minilm"), ch=(16,))
g("Harness configuration knobs", "harness", "E5 and E6 compare the settings each harness exposes: Claude Code's /compact, /context, model_auto_compact_token_limit, and CLAUDE.local.md; OpenCode's compaction settings and its opencode export and stats commands; Cursor's .cursor/rules .mdc files with 'Apply Intelligently'; and Gemini CLI's GEMINI.md and context.fileName.", "", "The control surface differs by harness, and the control-surface matrix records which rules each harness enforces and which it only requests.","https://gzkit.org/governance/agents-md-doctrine/", aliases=("control-surface matrix", "/compact", "/context", "CLAUDE.local.md", "GEMINI.md", "agents-md doctrine"), ch=(14, 15))
g("Routing and model families", "method", "E9 builds cost-aware routing. RouteLLM and FrugalGPT route to the cheap model first and escalate on doubt. A route table carries a budget, and degraded mode is what the system does when the preferred route is down. The open-weight families the decks list as adversaries from another family are GLM, DeepSeek, Kimi, Qwen, MiniMax, MiMo, and Nemotron. A stealth model is one whose family is undisclosed (Big Pickle).", "RouteLLM (Ong et al., 2024); FrugalGPT (Chen, Zaharia & Zou, 2023).", "The second-family adversary in E9's build is drawn from this list.","Course Topic Guide, Chapter 18", aliases=("RouteLLM", "FrugalGPT", "degraded mode", "stealth model", "DeepSeek", "Qwen", "Kimi", "GLM", "Nemotron"), ch=(18,))
g("gz commands", "course", "The decks cite these gzkit CLI verbs: gz init, gz prd, gz adr (and gz adr evaluate --red-team), gz validate (with --distribution, --instructions-files-budget, --invariant-coherence), gz handoff, gz insights remember (the corpus of operator corrections), gz obpi dispatch / lock / repudiate / complete, gz covers, gz arb red, gz patch release, gz closeout --ceremony, and gz status.", "", "gzkit is the course's reference design.","https://gzkit.org/user/quickstart/", aliases=("gz validate", "gz handoff", "gz obpi", "gz closeout", "gz insights", "insights corpus"), ch=(25,))
g("ADR-1 apparatus", "course", "E2 supplies these tools for writing the first ADR. WWHTBT asks what would have to be true. The pre-mortem assumes the design failed and asks why. Constraint archaeology asks where each constraint came from. The ten peer challenges, the decomposition scorecard, and the abstraction tax (what each layer costs on every call) complete the set.", "", "","Course Topic Guide, Chapter 11", aliases=("WWHTBT", "pre-mortem", "constraint archaeology", "abstraction tax", "decomposition scorecard"), ch=(11,))
g("gzkit founding documents", "course", "gzkit's founding documents are why.md (the Degradation Pattern, the reason the kit exists), the charter (what the kit promises), the lineage (where it came from), the genesis (the origin transcript), the command doctrine (how commands may act), the control-surface matrix, and the guides (guide-prd, guide-adr, guide-tasks, guide-releasing).", "", "The orientation lists them as readings, and each one is linked from the textbook's Readings.","https://gzkit.org/user/reference/", aliases=("why.md", "genesis.md", "charter", "lineage", "command doctrine"), ch=(3,))
g("Sprint and Drift essays", "course", "Sprint and Drift is the newsletter whose essays open the chapters. The essays are Tree Hollow, Who answers for the code, Enthusiasm Is All You Need, Get the Balance Right, Stop the presses, hail the autoloom, The cost of the wrong abstraction went to zero, Woven, Code ergo sum, Optimism's flames, Newtonian motion, Can you outrun the truth?, and Turn and Face the Change.", "sprintanddrift.substack.com (June–July 2026).", "Each chapter's Readings links the essay it opens with.","https://sprintanddrift.substack.com", aliases=("Who answers for the code", "Newtonian motion", "Turn and Face the Change", "Code ergo sum", "Woven", "Optimism's flames"), ch=(22,))
g("JADE, Voyager, OpenHands, Aider, Jules, Zed", "system", "These are entries in the survey tables. JADE is the Java FIPA-compliant agent platform of the 2000s. Voyager (2023) is a Minecraft agent that writes and stores its skills as code. OpenHands (2024) is an open-source coding-agent platform. Aider (2023) is a terminal pair-programming tool. Jules (2025) is Google's asynchronous coding agent. Zed is an editor with agent features.", "", "In the textbook, JADE appears in Chapter 4, Voyager in Chapters 6 and 16, and OpenHands and Aider in Chapter 7.","", aliases=("JADE", "Voyager", "OpenHands", "Aider", "Jules", "Zed"), ch=(4, 6, 7))
